create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null check(role in('athlete','coach','admin')),created_at timestamptz default now());
create table public.athletes(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.profiles(id) on delete cascade,sport text,position text,grad_year int,school text,city text,state text,height text,weight int,gpa numeric,bio text,stats jsonb default '{}',measurements jsonb default '{}',verified_metrics int default 0,profile_complete int default 0,is_searchable boolean default true,created_at timestamptz default now());
create table public.videos(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.athletes(id) on delete cascade,title text not null,sport text,storage_path text not null,public_url text,visibility text default 'coaches' check(visibility in('private','coaches','public')),created_at timestamptz default now());
create table public.film_reviews(id uuid primary key default gen_random_uuid(),athlete_id uuid references public.athletes(id) on delete cascade,video_id uuid references public.videos(id) on delete cascade,requested_by uuid references public.profiles(id),report jsonb not null,model text,created_at timestamptz default now());
create table public.recruiting_reports(id uuid primary key default gen_random_uuid(),athlete_id uuid references public.athletes(id) on delete cascade,requested_by uuid references public.profiles(id),report jsonb not null,model text,created_at timestamptz default now());
create table public.saved_prospects(id uuid primary key default gen_random_uuid(),coach_id uuid references public.profiles(id) on delete cascade,athlete_id uuid references public.athletes(id) on delete cascade,stage text default 'watching',notes text,unique(coach_id,athlete_id));
create table public.messages(id uuid primary key default gen_random_uuid(),sender_id uuid references public.profiles(id),recipient_id uuid references public.profiles(id),body text not null,created_at timestamptz default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid unique references public.profiles(id),plan text,status text,stripe_customer_id text,stripe_subscription_id text,updated_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'role','athlete')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create view public.athlete_directory with (security_invoker=true) as select a.*,p.full_name from public.athletes a join public.profiles p on p.id=a.user_id where a.is_searchable=true;
alter table public.profiles enable row level security;alter table public.athletes enable row level security;alter table public.videos enable row level security;alter table public.film_reviews enable row level security;alter table public.recruiting_reports enable row level security;alter table public.saved_prospects enable row level security;alter table public.messages enable row level security;alter table public.subscriptions enable row level security;
create policy "profiles readable authenticated" on public.profiles for select to authenticated using(true);create policy "profile owner update" on public.profiles for update to authenticated using(auth.uid()=id);
create policy "searchable athletes readable" on public.athletes for select to authenticated using(is_searchable or user_id=auth.uid());create policy "athlete owner write" on public.athletes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "coach visible video read" on public.videos for select to authenticated using(visibility in('coaches','public') or athlete_id in(select id from public.athletes where user_id=auth.uid()));create policy "athlete video write" on public.videos for all to authenticated using(athlete_id in(select id from public.athletes where user_id=auth.uid())) with check(athlete_id in(select id from public.athletes where user_id=auth.uid()));
create policy "review participants read" on public.film_reviews for select to authenticated using(requested_by=auth.uid() or athlete_id in(select id from public.athletes where user_id=auth.uid()));create policy "authenticated create reviews" on public.film_reviews for insert to authenticated with check(requested_by=auth.uid());
create policy "report participants read" on public.recruiting_reports for select to authenticated using(requested_by=auth.uid() or athlete_id in(select id from public.athletes where user_id=auth.uid()));create policy "authenticated create reports" on public.recruiting_reports for insert to authenticated with check(requested_by=auth.uid());
create policy "coach board own" on public.saved_prospects for all to authenticated using(coach_id=auth.uid()) with check(coach_id=auth.uid());
create policy "message participants read" on public.messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid());create policy "sender creates message" on public.messages for insert to authenticated with check(sender_id=auth.uid());
create policy "subscription owner read" on public.subscriptions for select to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('athlete-videos','athlete-videos',true,524288000,array['video/mp4','video/quicktime','video/webm']) on conflict(id) do nothing;
create policy "video upload own folder" on storage.objects for insert to authenticated with check(bucket_id='athlete-videos' and (storage.foldername(name))[1] in(select id::text from public.athletes where user_id=auth.uid()));create policy "video public read" on storage.objects for select using(bucket_id='athlete-videos');
